export default async function main({wb,log}){ const fs=await import('node:fs'); const zlib=await import('node:zlib'); const b=fs.readFileSync('input.xlsx'); let i=b.length-22; while(b.readUInt32LE(i)!==0x06054b50) i--; let n=b.readUInt16LE(i+10), p=b.readUInt32LE(i+16); let x=''; for(let k=0;k<n;k++){ const m=b.readUInt16LE(p+10), cs=b.readUInt32LE(p+20), fl=b.readUInt16LE(p+28), el=b.readUInt16LE(p+30), cl=b.readUInt16LE(p+32), off=b.readUInt32LE(p+42); const name=b.toString('utf8',p+46,p+46+fl); if(name.endsWith('sheet1.xml')){ const lf=b.readUInt16LE(off+26), le=b.readUInt16LE(off+28); x=zlib.inflateRawSync(b.subarray(off+30+lf+le,off+30+lf+le+cs)).toString('utf8'); } p+=46+fl+el+cl; }
 const un=t=>t.replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&apos;/g,"'").replace(/&quot;/g,'"').replace(/&amp;/g,'&');
 const orig={}; for(const m of x.matchAll(/<c r="BD(\d+)"[^>]*><is><t[^>]*>([^<]*)<\/t><\/is><\/c>/g)) orig[m[1]]=un(m[2]);
 const s=wb.getWorksheet('Sheet1'); let diff=[],same=0,blank=[],rich=[];
 for(let r=2;r<=308;r++){const c=s.getRange('BD'+r).getCell();const v=c.getValue();const o=orig[r];if(o===undefined){ if(v===null||v===undefined||v==='') blank.push(r); else diff.push(r); continue;} if(String(v)===o) same++; else diff.push(r+':'+JSON.stringify(v)); const rt=c.getRichText(); if(rt) rich.push(r+' '+JSON.stringify(rt));}
 log('same',same,'diff',diff.join(';'),'blank',blank.length,blank.join(','));
 log(rich.join('\n'));
 log('formula evaluates', await wb.evaluate('=LEN(BD3)&"|"&TYPE(BD3)&"|"&BD272'));
}

